function customItem(index){const i=Number.isInteger(index)?draft.items[index]:null;modal(i?'Edit custom item':'Add custom item',`<form>${input('name','Custom item name',i?.name||'','text','required maxlength="160"')}<div class="fields">${input('price','Unit price · PHP',amount(i?.unit_price_cents),'number','required min="0" step="0.01"')}${input('quantity','Quantity',i?.quantity||1,'number','required min="1" max="10000" step="1"')}</div><p class="muted">Custom items have no inventory deduction. Choose a website product from the catalog when it should use website stock.</p><button type="submit" class="primary">Save custom item</button></form>`,async f=>{const item={product_id:i?.product_id||uid(),source:'custom',name:f.get('name').trim(),unit_price_cents:cents(f.get('price')),quantity:Number(f.get('quantity')),selections:{}};if(i)draft.items[index]=item;else draft.items.push(item);dialog.close();render();});}
function productForm(p){modal(p?'Edit POS-only product':'Add POS-only product',`<form>${input('name','Product name',p?.name||'','text','maxlength="160"')}${input('price','Price · PHP',amount(p?.price_cents),'number','required min="0" step="0.01"')}${select('stock_mode','Inventory',[['daily','Separate quantity per date'],['running','Running stock across dates'],['unlimited','Unlimited']],p?.stock_mode||'running')}<label class="check"><input name="active" type="checkbox" ${p?.active!==false?'checked':''}>Available for direct orders</label><button class="primary" type="submit">Save product</button></form>`,async f=>{await api('pos_save_product',{id:p?.id||uid(),revision:p?.revision||0,name:f.get('name'),description:p?.description||'',price_cents:cents(f.get('price')),stock_mode:f.get('stock_mode'),photo:p?.photo||'',active:f.has('active')});await load();dialog.close();render();});}
function stockProduct(p){modal('Adjust POS product stock',`<form><p>${esc(p.name)} · ${p.stock_mode==='running'?'All dates':esc(draft.fulfillment_date)}</p>${input('available','Available units now',p.remaining,'number','required min="0" max="1000000" step="1"')}${input('reason','Reason','','text','required maxlength="1000"')}<button class="primary" type="submit">Save stock</button></form>`,async f=>{await api('pos_set_stock',{id:p.id,date:draft.fulfillment_date,available:Number(f.get('available')),expected_available:p.remaining,reason:f.get('reason')});await load();dialog.close();render();});}
async function loadReport(){report=eventId?await api('pos_event_report',{event_id:eventId,date:reportDate}):null;}
function renderReport(){if(!event)return '<p class="notice">Choose an event first.</p>';if(!report)return '<p>Loading report…</p>';const total=report.sales.reduce((s,x)=>s+Number(x.total_cents),0),count=report.sales.reduce((s,x)=>s+Number(x.orders),0),c=report.cash;
 return `<div class="section-head">${accountingDatePicker('report_date','Report day',reportDate,today(),{attrs:'id="report-date"'})}${button('refresh-report','Refresh report')}</div><div class="metrics"><div class="metric">Sales including delivery<strong>${money(total)}</strong></div><div class="metric">Paid orders<strong>${count}</strong></div><div class="metric">Expected cash in drawer<strong>${c?money(c.expected_cents):'Not opened'}</strong></div></div><section class="panel"><h2>Sales by payment method</h2><p class="muted">Cancelled and refunded orders are excluded. Sales are already included in Accounting.</p><div class="table-wrap"><table><thead><tr><th>Method</th><th>Orders</th><th class="num">Sales</th><th class="num">Delivery included</th></tr></thead><tbody>${report.sales.map(s=>`<tr><td>${esc(s.method)}</td><td>${s.orders}</td><td class="num">${money(s.total_cents)}</td><td class="num">${money(s.delivery_cents)}</td></tr>`).join('')||'<tr><td colspan="4">No sales for this day.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="section-head"><h2>Cash reconciliation</h2><div class="row">${c&&!c.closed_at?button('cash-movement','Record cash in / out')+button('close-cash','Count & close'):c?.closed_at&&role==='owner'?button('reopen-cash','Reopen session'):!c&&reportDate===today()?button('open-cash','Open cash session'):''}</div></div><p class="muted">Expected cash = opening float + cash payments received + cash in − cash out. Cancellations and refund labels do not mean money has left the drawer: record an actual cash refund as cash out. Cash movements do not create extra accounting entries.</p>${c?`<div class="totals"><div><span>Opening float</span><strong>${money(c.opening_cents)}</strong></div><div><span>Expected cash</span><strong>${money(c.expected_cents)}</strong></div>${c.closed_at?`<div><span>Counted cash</span><strong>${money(c.counted_cents)}</strong></div><div class="grand"><span>Over / short at close</span><strong>${money(c.counted_cents-c.expected_at_close)}</strong></div>`:''}</div>`:'<p>No cash session for this date.</p>'}${report.movements.length?`<div class="table-wrap"><table><thead><tr><th>Cash movement</th><th class="num">Amount</th></tr></thead><tbody>${report.movements.map(m=>`<tr><td>${esc(m.reason)}</td><td class="num">${money(m.amount_cents)}</td></tr>`).join('')}</tbody></table></div>`:''}</section><section class="panel"><h2>Remaining event stock</h2><p class="muted">Current stock across the whole event.</p><div class="table-wrap"><table><thead><tr><th>Stock item</th><th class="num">Remaining</th></tr></thead><tbody>${report.stock.map(s=>`<tr><td>${esc(s.name)}</td><td class="num">${s.remaining}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function cashForm(action){const c=view==='report'?report?.cash:event?.cash_session,date=view==='report'?reportDate:today(),movementId=uid();const fields=action==='pos_open_cash'?input('opening','Opening cash float · PHP','0.00','number','required min="0" step="0.01"'):action==='pos_close_cash'?`<p>Expected: <strong>${money(c.expected_cents)}</strong></p>${input('counted','Cash counted · PHP','','number','required min="0" step="0.01"')}`:action==='pos_reopen_cash'?input('reason','Reason for reopening','','text','required maxlength="1000"'):`${select('direction','Cash direction',[['in','Cash in'],['out','Cash out']],'out')}${input('amount','Amount · PHP','','number','required min="0.01" step="0.01"')}${input('reason','Reason (e.g. cash refund, float added)','','text','required maxlength="1000"')}`;
 modal(({pos_open_cash:'Open cash session',pos_close_cash:'Count & close',pos_reopen_cash:'Reopen cash session',pos_cash_movement:'Record cash movement'})[action],`<form>${fields}<button type="submit" class="primary">Save</button></form>`,async f=>{await api(action,{event_id:eventId,date,revision:c?.revision,id:movementId,opening_cents:f.has('opening')?cents(f.get('opening')):undefined,counted_cents:f.has('counted')?cents(f.get('counted')):undefined,expected_cents:c?.expected_cents,amount_cents:f.has('amount')?cents(f.get('amount'))*(f.get('direction')==='out'?-1:1):undefined,reason:f.get('reason')});await load();await loadReport();dialog.close();render();});
}
async function copyPaymentLink(id){const o=await api('pos_payment_link',{order_id:id}),url=new URL('order.html',location.href);url.hash=new URLSearchParams({order:o.id,token:o.token}).toString();try{await navigator.clipboard.writeText(url.href);status('Private order / payment link copied.');}catch{modal('Private payment link',`<p>Anyone with this link can view the order. Send it only to the customer.</p><label>Copy this link<input readonly value="${esc(url.href)}"></label>`);dialog.querySelector('input').select();}}
// Keep the same request on an uncertain network response; known validation failures can be corrected.
function deliveryDialog(title,fields,action,o,values){let request=null;
 modal(title,'<form>'+fields+'<button class="primary subheading" type="submit">Save</button></form>',async f=>{
  request??={order_id:o.id,revision:o.revision,idempotency_key:uid(),...values(f)};
  try{await api(action,request);}catch(e){if(e.code==='P0001'||/^22|^23/.test(e.code||''))request=null;else dialog.querySelectorAll('input,select').forEach(el=>el.disabled=true);throw e;}
  await load();dialog.close();render();status('Delivery details saved.');
 });
}
function deliveryFeeForm(o){const c=o.delivery_charge||{state:'included',recipient:'elio',fee_cents:o.delivery_cents},collected=c.state==='paid'||c.state==='included'&&o.payment_status==='paid'&&c.fee_cents>0;
 if(collected){modal('Delivery payment recorded','<p>'+esc(deliveryFeeSummary(o,money))+'</p><p>Correct the recorded delivery payment before changing who receives it. This does not issue a refund automatically.</p>'+(c.state==='paid'&&role==='owner'?button('void-delivery-payment','Correct delivery payment','data-id="'+o.id+'"'):'<p>This fee was included in the original order payment. Use the kitchen’s payment/refund correction process first.</p>'));return;}
 if(o.payment_status==='under_review'){modal('Payment under review','<p>Finish reviewing the initial payment before changing the delivery fee.</p>');return;}
 const fields='<p><strong>'+esc(o.reference)+'</strong></p>'+select('recipient','Customer pays delivery to',[['elio','Pay Elio'],['courier','Pay courier directly']],c.recipient)+input('fee','Exact delivery fee · PHP',c.fee_cents===null?'':amount(c.fee_cents),'number','min="0" step="0.01"')+'<small>Leave the amount blank while the fee is still to be confirmed.</small>'+input('reason','Reason / booking reference','','text','required maxlength="1000"')+(c.state==='quoted'?'<p>The delivery fee has not been received by Elio. Changing the recipient updates the amount due.</p>'+button('delivery-payment','Record delivery payment','data-id="'+o.id+'"'):'');
 deliveryDialog('Edit delivery fee',fields,'pos_set_delivery_fee',o,f=>({recipient:f.get('recipient'),fee_cents:String(f.get('fee')).trim()===''?null:cents(f.get('fee')),reason:f.get('reason')}));
}
function deliveryPaymentForm(o){const methods=[['cash','Cash'],...(catalog.payment_options||[]).map(x=>[x.label,x.label])];
 deliveryDialog('Record delivery payment','<p>Confirm Elio received <strong>'+money(o.delivery_charge.fee_cents)+'</strong> for delivery. The product payment stays unchanged.</p>'+select('method','Payment method',methods,'cash')+input('reference','Payment reference · optional','','text','maxlength="160"')+'<label class="check"><input type="checkbox" required>Full delivery payment received by Elio</label>','pos_record_delivery_payment',o,f=>({method:f.get('method'),reference:f.get('reference')}));
}
function voidDeliveryPayment(o){deliveryDialog('Correct delivery payment','<p>This reverses the separate delivery receipt in accounting and keeps its history. It does not transfer money.</p><label class="check"><input name="refund_confirmed" type="checkbox" required>The delivery payment was returned to the customer, or was recorded in error</label>'+input('reason','Correction reason','','text','required maxlength="1000"'),'pos_void_delivery_payment',o,f=>({refund_confirmed:f.has('refund_confirmed'),reason:f.get('reason')}));}
function chooseBoxFlavors(p){
 const limit=3,choices=mode==='in_person'?event.stock.filter(f=>p.choice_stock_ids.includes(f.id)).map(f=>({...f,price_cents:f.surcharge_cents,remaining:Math.max(0,f.remaining+eventStockUsed(editing?.items||[],f.id)-eventStockUsed(draft.items,f.id))})):catalog.flavors,selected=new Map(choices.map(f=>[f.id,0]));
 modal('Choose '+limit+' flavor pieces',`<form class="flavor-picker"><p id="flavor-selection-status" class="muted" role="status" aria-live="polite">0 of ${limit} selected</p>${choices.map(f=>`<div class="flavor-choice"><span class="flavor-name">${esc(f.name)}${f.remaining===0?'<small>Unavailable</small>':''}${f.price_cents?`<small>+${money(f.price_cents)} per piece</small>`:''}</span><div class="flavor-stepper" role="group" aria-label="${esc(f.name)} quantity"><button type="button" data-flavor-minus="${esc(f.id)}" aria-label="Remove one ${esc(f.name)}" disabled>−</button><output data-flavor-count="${esc(f.id)}" aria-label="${esc(f.name)} pieces">0</output><button type="button" data-flavor-plus="${esc(f.id)}" aria-label="Add one ${esc(f.name)}">+</button></div></div>`).join('')}<button class="primary subheading" type="submit" disabled>Add box</button></form>`,async()=>{
  const flavors=Object.fromEntries([...selected].filter(([,n])=>n>0));
  if(Object.values(flavors).reduce((a,b)=>a+b,0)!==limit)throw Error('Choose exactly '+limit+' pieces.');
  pushItem(p,{flavors});dialog.close();render();
 });
 const form=dialog.querySelector('form'),total=()=>[...selected.values()].reduce((a,b)=>a+b,0);
 function update(){const count=total();
  form.querySelectorAll('[data-flavor-count]').forEach(el=>el.textContent=selected.get(el.dataset.flavorCount));
  form.querySelectorAll('[data-flavor-minus]').forEach(el=>el.disabled=selected.get(el.dataset.flavorMinus)===0);
  form.querySelectorAll('[data-flavor-plus]').forEach(el=>el.disabled=count>=limit||selected.get(el.dataset.flavorPlus)>=(choices.find(f=>f.id===el.dataset.flavorPlus)?.remaining??Infinity));
  form.querySelector('[type=submit]').disabled=count!==limit;
  form.querySelector('[role=status]').textContent=count+' of '+limit+' selected'+(count===limit?' · Remove a piece to change flavors.':'');
 }
 form.querySelectorAll('[data-flavor-plus],[data-flavor-minus]').forEach(el=>el.onclick=()=>{
  if(busy)return;const id=el.dataset.flavorPlus||el.dataset.flavorMinus,previous=selected.get(id);
  if(el.hasAttribute('data-flavor-plus')){if(total()<limit&&previous<(choices.find(f=>f.id===id)?.remaining??Infinity))selected.set(id,previous+1);}else if(previous>0)selected.set(id,previous-1);
  update();
 });
 update();
}
function addItem(id){readDraft();const p=product(id);if(!p)return;if(p.kind==='custom_box')chooseBoxFlavors(p);else{pushItem(p,{});render();}}
function pushItem(p,selections){const existing=draft.items.find(i=>i.product_id===p.id&&JSON.stringify(i.selections)===JSON.stringify(selections));if(existing)existing.quantity++;else draft.items.push({product_id:p.id,source:p.source||'event',quantity:1,selections,name:p.name});}
async function editOrder(id){const o=await api('get_order',{order_id:id});if(['completed','cancelled','expired'].includes(o.fulfillment_status)||o.refund_label){mode=o.order_source;view='orders';await load();render();return;}if(!['direct','in_person'].includes(o.order_source))throw Error('Use the kitchen editor for this order.');mode=o.order_source;eventId=o.event_id||'';editing=o;draft={...newDraft(),...structuredClone(o),payment:o.pos_payment||{method:'cash',cash_received_cents:0,reference:''},reason:'',items:structuredClone(o.items)};await load();view='sale';render();}
function payOrder(o){let p={method:'cash',cash_received_cents:o.total_cents,reference:''},request=null;const draw=()=>{modal('Record full payment',`<form><p><strong>${esc(o.reference)}</strong> · ${money(o.total_cents)} due</p>${paymentFields(p)}<button class="primary" type="submit">Record payment received</button></form>`,async f=>{request??={order_id:o.id,revision:o.revision,idempotency_key:uid(),payment:{method:f.get('payment_method'),cash_received_cents:cents(f.get('cash_received')||'0'),reference:String(f.get('payment_reference')||'')}};let saved;try{saved=await api('pos_pay_order',request);}catch(error){if(error.code==='P0001'||/^22|^23/.test(error.code||''))request=null;else{dialog.querySelectorAll('input,select').forEach(el=>el.disabled=true);}throw error;}await load();dialog.close();render();showSaved(saved);});dialog.querySelector('[name=payment_method]').onchange=e=>{p.method=e.target.value;dialog.close();draw();};};draw();}
async function action(name,id){
 if(name.startsWith('mode-')){readDraft();if(draft.items.length&&!confirm('Clear this unsaved cart and change POS section?'))return;mode=name==='mode-person'?'in_person':'direct';draft=newDraft();editing=null;view='sale';await load();render();return;}
 if(name.startsWith('view-')){readDraft();view=name.slice(5);if(view==='report')await loadReport();render();return;}
 switch(name){
 case 'delivery-fee':deliveryFeeForm(await api('get_order',{order_id:id}));break;case 'delivery-payment':deliveryPaymentForm(await api('get_order',{order_id:id}));break;case 'void-delivery-payment':voidDeliveryPayment(await api('get_order',{order_id:id}));break;
 case 'custom-item':readDraft();customItem();break;case 'edit-custom-item':readDraft();customItem(Number(id));break;
 case 'delete-event':deleteEventRecord('event');break;case 'delete-event-stock':deleteEventRecord('stock',id);break;case 'delete-event-item':deleteEventRecord('item',id);break;case 'import-event-flavors':importEventCatalog(true);break;case 'import-event-products':importEventCatalog(false);break;
 case 'new-event':eventForm();break;case 'edit-event':eventForm(event);break;case 'new-event-stock':eventStockForm();break;case 'edit-event-stock':eventStockForm(event.stock.find(x=>x.id===id));break;
 case 'new-event-item':eventItemForm();break;case 'edit-event-item':eventItemForm(event.items.find(x=>x.id===id));break;
 case 'new-product':productForm();break;case 'edit-product':productForm(catalog.pos_products.find(x=>x.id===id));break;case 'stock-product':stockProduct(catalog.pos_products.find(x=>x.id===id));break;
 case 'delete-product':{const p=catalog.pos_products.find(x=>x.id===id);if(confirm(`Delete ${p.name} from the POS catalog? Existing orders and records will stay intact.`)){await api('pos_delete_product',{id,revision:p.revision});await load();render();}break;}
 case 'open-cash':cashForm('pos_open_cash');break;case 'close-cash':cashForm('pos_close_cash');break;case 'reopen-cash':cashForm('pos_reopen_cash');break;case 'cash-movement':cashForm('pos_cash_movement');break;
 case 'refresh-report':await loadReport();render();break;case 'payment-link':await copyPaymentLink(id);break;case 'open-order':location.href=`manage.html?order=${encodeURIComponent(id)}`;break;
 case 'copy-buyer':readDraft();draft.recipient={name:draft.buyer.name,phone:draft.buyer.phone};render();break;case 'back-review':pending=null;render();break;case 'save-sale':await saveSale();break;
 case 'next-sale':dialog.close();view='sale';draft=newDraft();render();break;case 'pay-order':payOrder(orders.find(o=>o.id===id));break;case 'edit-order':await editOrder(id);break;
 case 'cancel-edit':editing=null;draft=newDraft();view='orders';render();break;
 }
}
async function run(fn){if(busy)return;try{busy=true;$('#refresh').disabled=true;await fn();}catch(e){flashError(e);}finally{busy=false;$('#refresh').disabled=false;}}
function bind(){
 root.querySelectorAll('[data-payment-method]').forEach(b=>b.onclick=()=>run(()=>{readDraft();draft.payment.method=b.dataset.paymentMethod;render();}));
 root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>run(()=>addItem(b.dataset.add)));
 root.querySelectorAll('[data-qty]').forEach(i=>i.onchange=()=>run(()=>{readDraft();const n=Number(i.value);if(!Number.isInteger(n)||n<1||n>10000)throw Error('Enter a whole quantity between 1 and 10,000.');draft.items[Number(i.dataset.qty)].quantity=n;render();}));
 root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>run(()=>{readDraft();draft.items.splice(Number(b.dataset.remove),1);render();}));
 const f=$('#sale-form');if(f){f.onsubmit=e=>{e.preventDefault();run(review);};for(const name of ['method','paid','payment_method','pos_handed_over','delivery_fee_recipient','delivery_fee_pending'])f.elements[name]?.addEventListener('change',()=>run(()=>{readDraft();render();}));if(f.elements.fulfillment_date)f.elements.fulfillment_date.onchange=()=>run(async()=>{readDraft();catalog=await api('pos_catalog',{date:draft.fulfillment_date});render();});f.elements.cash_received?.addEventListener('input',e=>{const value=Number(e.target.value);if($('#cash-change'))$('#cash-change').textContent=money(Math.max(0,Math.round(value*100)-estimated()));});}
 $('#search')?.addEventListener('input',e=>{search=e.target.value;const cursor=e.target.selectionStart;readDraft();render();$('#search').focus();$('#search').setSelectionRange(cursor,cursor);});
 $('#show-deleted-events')?.addEventListener('change',e=>run(async()=>{showDeletedEvents=e.target.checked;await load();if(view==='report')await loadReport();render();}));
 $('#event-select')?.addEventListener('change',e=>run(async()=>{if(draft.items.length&&!confirm('Clear the current cart and switch event?')){e.target.value=eventId;return;}eventId=e.target.value;draft=newDraft();await load();if(view==='report')await loadReport();render();}));
 $('#report-date')?.addEventListener('change',e=>run(async()=>{reportDate=e.target.value;await loadReport();render();}));
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();run(()=>action(b.dataset.action,b.dataset.id));}});
$('#refresh').onclick=()=>run(async()=>{if(pending){status('Finish or retry the pending request first.');return;}readDraft();await load();if(view==='report')await loadReport();render();status('Stock and orders refreshed.');});
window.addEventListener('beforeunload',e=>{if(pending||draft.items.length){e.preventDefault();e.returnValue='';}});
window.addEventListener('offline',()=>{status('Connection lost. Sales require internet.');});window.addEventListener('online',()=>status('Connection restored. Refresh to see current stock.'));
await ready;
try{const access=await api('account_access');if(!['owner','staff'].includes(access.role))throw Error('Sign in with an authorized Elio team account.');role=access.role;await load();const edit=new URLSearchParams(location.search).get('edit');if(edit)await editOrder(edit);else render();auth?.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){draft=newDraft();pending=null;location.replace('admin-account.html?next=pos.html');}});if('serviceWorker' in navigator)navigator.serviceWorker.register('pos-sw.js',{scope:'./'}).catch(()=>{});}catch(error){root.innerHTML=`<section class="panel"><h1>Elio POS</h1><p>${esc(error.message)}</p><a class="button" href="admin-account.html?next=pos.html">Team sign in</a></section>`;}
